+// SelectableFields returns the declared selectable fields for a kind.
+func (r *SearchFieldsRegistry) SelectableFields(key LowerGroupResource) []string {
+	if r == nil {
+		return nil
+	}
+	r.mu.RLock()
+	defer r.mu.RUnlock()
+	return r.selectableFields[key]
+}
+
+// HasSelectableField reports whether the kind declares the given field as selectable.
+func (r *SearchFieldsRegistry) HasSelectableField(key LowerGroupResource, field string) bool {
+	if r == nil {
+		return false
+	}
+	field = strings.TrimPrefix(field, SEARCH_SELECTABLE_FIELDS_PREFIX)
+	r.mu.RLock()
+	defer r.mu.RUnlock()
+	return slices.Contains(r.selectableFields[key], field)
+}
